CREATE TABLE "__mistri_assistant_meta" (
  singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
  version INTEGER NOT NULL CHECK (version = 1)
);
CREATE TABLE "__mistri_assistant_conversation" (
  id TEXT COLLATE BINARY PRIMARY KEY,
  app TEXT COLLATE BINARY NOT NULL CHECK (length(CAST(app AS BLOB)) <= 128),
  tenant TEXT COLLATE BINARY NOT NULL CHECK (length(CAST(tenant AS BLOB)) <= 128),
  account TEXT COLLATE BINARY NOT NULL CHECK (length(CAST(account AS BLOB)) <= 1024),
  title TEXT NOT NULL CHECK (length(CAST(title AS BLOB)) <= 200),
  state TEXT NOT NULL CHECK (state IN ('idle', 'awaiting')),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE "__mistri_assistant_event" (
  conversation TEXT COLLATE BINARY NOT NULL,
  seq INTEGER NOT NULL,
  kind TEXT NOT NULL,
  body_json TEXT NOT NULL CHECK (json_valid(body_json) AND length(CAST(body_json AS BLOB)) <= 524288),
  at TEXT NOT NULL,
  PRIMARY KEY (conversation, seq)
);
CREATE TABLE "__mistri_assistant_usage" (
  app TEXT COLLATE BINARY NOT NULL,
  tenant TEXT COLLATE BINARY NOT NULL,
  account TEXT COLLATE BINARY NOT NULL,
  day TEXT NOT NULL,
  tokens INTEGER NOT NULL,
  PRIMARY KEY (app, tenant, account, day)
);
CREATE INDEX "__mistri_assistant_conversation_owner" ON "__mistri_assistant_conversation" (app, tenant, account, updated_at);
CREATE TABLE "__mistri_switch_meta" (
  singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
  version INTEGER NOT NULL CHECK (version = 1)
);
CREATE TABLE "__mistri_switch_tenant" (
  app TEXT COLLATE BINARY NOT NULL CHECK (length(CAST(app AS BLOB)) <= 128),
  tenant TEXT COLLATE BINARY NOT NULL CHECK (length(CAST(tenant AS BLOB)) <= 128),
  feature TEXT COLLATE BINARY NOT NULL CHECK (length(CAST(feature AS BLOB)) <= 64),
  enabled INTEGER NOT NULL CHECK (enabled IN (0, 1)),
  consent TEXT NOT NULL CHECK (length(CAST(consent AS BLOB)) <= 2000),
  changed_at TEXT NOT NULL,
  PRIMARY KEY (app, tenant, feature)
);
